def generate(rng):
    # Create a checkerboard-like 21x21 field with a few rectangular erased regions.
    h = rng.choice([9, 13, 17, 21])
    w = rng.choice([9, 13, 17, 21])
    a, b, c = rng.sample([1, 2, 3], 3)
    grid = []
    for r in range(h):
        row = []
        for col in range(w):
            if r % 2 == 0:
                row.append(c if col % 2 == 0 else b)
            else:
                row.append(b if col % 2 == 0 else a)
        grid.append(row)
    # Erasures are aligned to the alternating lattice and may touch/overlap.
    for _ in range(rng.randint(1, 4)):
        r0 = rng.randrange(h)
        c0 = rng.randrange(w)
        rh = rng.choice([1, 2, 3, 4])
        rw = rng.choice([1, 2, 3, 4])
        for r in range(r0, min(h, r0 + rh)):
            for col in range(c0, min(w, c0 + rw)):
                grid[r][col] = 0
    return grid"}

